write('server/tests/duplicateEvidenceIntegrityEngine.test.ts', r'''import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import {buildDuplicateEvidenceFiveDimensionChecks} from '../cpaOrganization/duplicateEvidenceIntegrityEngine.js';import {prepareDuplicateEvidence} from './fixtures/duplicateEvidenceAcceptanceHelpers.js';import {duplicateEvidenceDir} from './fixtures/duplicateEvidenceFixture.js';const p=await prepareDuplicateEvidence();assert.equal(p.cleanReview.status,'VERIFIED_DUPLICATE_CONTROL');assert.equal(p.cleanReview.inputObservationCount,6);assert.equal(p.cleanReview.evidenceIdentityCount,2);assert.equal(p.cleanReview.independentCorroborationCount,2);assert.equal(p.cleanReview.suppressedExactDuplicateCount,2);assert.equal(p.cleanReview.suppressedCosmeticNearDuplicateCount,2);assert.equal(p.cleanReview.materialConflictCount,0);assert.equal(p.conflictReview.status,'BLOCKED_MATERIAL_NEAR_DUPLICATE_CONFLICT');assert.equal(p.conflictReview.promotionState,'BLOCKED_MATERIAL_CONFLICT');assert.equal(p.conflictReview.decision,'REQUEST_MATERIAL_SOURCE_RECONCILIATION');assert.equal(p.conflictReview.inputObservationCount,8);assert.equal(p.conflictReview.uniquePhysicalSourceCount,6);assert.equal(p.conflictReview.independentCorroborationCount,2);assert.equal(p.conflictReview.materialConflictCount,2);assert.equal(p.conflictReview.canonicalPromotedValue,null);assert.equal(p.invalidReview.status,'BLOCKED_INVALID_SOURCE_IDENTITY');for(const v of p.conflictReview.variants)assert.equal(v.arithmeticStatus,'PASS',`${v.documentId} arithmetic`);for(const kind of ['PDF','IMAGE']){const vs=p.conflictReview.variants.filter(v=>v.sourceKind===kind);assert.equal(vs.filter(v=>v.classification==='REPRESENTATIVE').length,1);assert.equal(vs.filter(v=>v.classification==='EXACT_DUPLICATE').length,1);assert.equal(vs.filter(v=>v.classification==='NEAR_DUPLICATE_EQUIVALENT').length,1);assert.equal(vs.filter(v=>v.classification==='NEAR_DUPLICATE_MATERIAL_CONFLICT').length,1);}const checks=buildDuplicateEvidenceFiveDimensionChecks(p.cleanReview,p.conflictReview);assert(checks.source.every(c=>c.outcome==='PASS'));assert(checks.semantic.every(c=>c.outcome==='PASS'));assert(checks.accounting.every(c=>c.outcome==='PASS'));fs.writeFileSync(path.join(duplicateEvidenceDir(),'source-truth.json'),JSON.stringify({marker:'P2_DUPLICATE_EVIDENCE_SOURCE_TRUTH=PASS',clean:p.cleanReview,conflict:p.conflictReview,invalid:p.invalidReview},null,2));console.log('P2_DUPLICATE_EVIDENCE_SOURCE_TRUTH=PASS');
''')

write('src/components/views/engagement/DuplicateEvidenceIntegrityPanel.tsx', r'''import React from 'react';const show=(v:any)=>v===null||v===undefined||v===''?'NOT RECORDED':String(v);const coord=(c:any)=>!c?'NOT RECORDED':c.sourceType==='PDF'?`PDF page=${c.pageNumber}`:c.sourceType==='IMAGE'?`IMAGE page=${c.pageNumber||1} region=${c.ocrRegionId||'NOT RECORDED'}`:`${c.sourceType||'SOURCE'}`;export const DuplicateEvidenceIntegrityPanel:React.FC<{review:any}>=({review})=>{if(!review)return null;return <section className="border rounded-xl p-4 space-y-3" data-eve-duplicate-evidence="true"><h2 className="font-semibold">Duplicate / near-duplicate evidence integrity review</h2><p>Status: <strong>{show(review.status)}</strong> · Promotion: <strong>{show(review.promotionState)}</strong></p><p>Action: {show(review.decision)}</p><p>Inputs: {show(review.inputObservationCount)} · Physical source SHAs: {show(review.uniquePhysicalSourceCount)} · Evidentiary identities: {show(review.evidenceIdentityCount)} · Independent corroboration: {show(review.independentCorroborationCount)}</p><p>Suppressed exact duplicates: {show(review.suppressedExactDuplicateCount)} · Suppressed cosmetic near-duplicates: {show(review.suppressedCosmeticNearDuplicateCount)} · Material conflicts: {show(review.materialConflictCount)}</p><p>Canonical promoted value: <strong>{review.canonicalPromotedValue==null?'NOT PROMOTED':show(review.canonicalPromotedValue)}</strong></p><p>Byte-identical and cosmetic-only copies never increase corroboration weight. A same-identity source with changed material accounting content remains separately traceable and blocks promotion.</p><div className="grid gap-3 md:grid-cols-2">{(review.variants||[]).map((v:any,i:number)=><article key={v.documentId||i} className="border rounded-lg p-3 space-y-1"><h3 className="font-medium">{show(v.sourceKind)} · {show(v.classification)}</h3><p>Document: {show(v.documentId)} · Total: USD {show(v.materialFields?.total)}</p><p>Representative: {show(v.representativeDocumentId)} · Corroboration weight: {show(v.corroborationWeight)}</p><p>Arithmetic: {show(v.arithmeticStatus)} · Coordinate: {coord(v.sourceCoordinate)}</p><p className="break-all">Source SHA-256: {show(v.sourceSha256)}</p><p className="break-all">Identity fingerprint: {show(v.identityFingerprint)}</p><p className="break-all">Material fingerprint: {show(v.materialFingerprint)}</p><p className="break-all">Provenance: {show(v.provenanceId)}</p><p>Issues: {(v.issues||[]).join(' | ')||'NONE'}</p></article>)}</div>{review.issues?.length>0&&<ul className="list-disc pl-5">{review.issues.map((x:string,i:number)=><li key={i}>{x}</li>)}</ul>}</section>;};
''')

write('server/tests/duplicateEvidenceDeliverableTruth.test.ts', r'''import assert from 'node:assert/strict';import crypto from 'node:crypto';import fs from 'node:fs';import path from 'node:path';import * as XLSXModule from 'xlsx';const XLSX:any=(XLSXModule as any).default||XLSXModule;import {prepareDuplicateEvidence} from './fixtures/duplicateEvidenceAcceptanceHelpers.js';import {duplicateEvidenceDir} from './fixtures/duplicateEvidenceFixture.js';const dir=duplicateEvidenceDir(),reports=path.join(dir,'reports');fs.mkdirSync(reports,{recursive:true});process.env.HERMES_REPORTS_DIR=reports;const {deliverableArtifactService}=await import('../cpaOrganization/deliverableArtifactService.js');const p=await prepareDuplicateEvidence();const report=await deliverableArtifactService.compileAndRegisterDeliverable({reportId:'REP-DUP-EVIDENCE',engagementId:'eng-academy-duplicate-evidence',workspaceId:'ws-academy-duplicate-evidence',version:'v1.0',title:'Duplicate Evidence Integrity Draft',clientName:'Eve Academy Duplicate Evidence',period:'FY 2026',currency:'USD',status:'AI_PREPARED',facts:p.facts.map((f:any)=>({id:f.id,canonicalMetric:f.canonicalMetric,label:f.labelNormalized,value:f.normalizedValue,statement:'EVIDENCE_INTEGRITY',sourceDoc:f.sourceDocument,documentId:f.documentId,reportingPeriod:f.reportingPeriod,verificationStatus:f.verificationStatus,evidenceStatus:f.evidenceStatus,sourceText:f.sourceText,sourceSha256:f.sourceSha256,sourceArtifactId:f.sourceArtifactId,sourceProvenanceId:f.sourceProvenanceId,sourceProvenanceIds:f.sourceProvenanceIds,sourceCoordinate:f.sourceCoordinate,sourceCoordinates:f.sourceCoordinates,sourceExtractionMethod:f.sourceExtractionMethod,sourceExtractionVersion:f.sourceExtractionVersion})),duplicateEvidenceReview:p.conflictReview});assert.ok(report.formats.pdf&&report.formats.json&&report.formats.xlsx&&report.formats.csvLeadSchedules);const pdf=fs.readFileSync(report.formats.pdf!.filepath);assert.equal(pdf.subarray(0,5).toString(),'%PDF-');assert.equal(crypto.createHash('sha256').update(pdf).digest('hex'),report.formats.pdf!.sha256);const {PDFParse}=await import('pdf-parse');const parser=new PDFParse({data:pdf});let text='';try{text=(await parser.getText()).text;}finally{await parser.destroy();}for(const expected of ['Duplicate / near-duplicate evidence integrity review','BLOCKED_MATERIAL_NEAR_DUPLICATE_CONFLICT','REQUEST_MATERIAL_SOURCE_RECONCILIATION','EXACT_DUPLICATE','NEAR_DUPLICATE_EQUIVALENT','NEAR_DUPLICATE_MATERIAL_CONFLICT','PDF','IMAGE','USD 53.23','USD 63.23','Corroboration weight: 0'])assert(text.includes(expected),`PDF missing ${expected}`);const json=JSON.parse(fs.readFileSync(report.formats.json!.filepath,'utf8'));assert.equal(json.duplicateEvidenceReview.status,'BLOCKED_MATERIAL_NEAR_DUPLICATE_CONFLICT');assert.equal(json.duplicateEvidenceReview.independentCorroborationCount,2);const csv=fs.readFileSync(report.formats.csvLeadSchedules!.filepath,'utf8');for(const e of ['DUPLICATE EVIDENCE INTEGRITY REVIEW','EXACT_DUPLICATE','NEAR_DUPLICATE_EQUIVALENT','NEAR_DUPLICATE_MATERIAL_CONFLICT'])assert(csv.includes(e),`CSV missing ${e}`);const wb=XLSX.readFile(report.formats.xlsx!.filepath);assert(wb.Sheets['Duplicate Evidence']);const sheet=(XLSX.utils.sheet_to_json(wb.Sheets['Duplicate Evidence'],{header:1,raw:false}) as any[][]).flat().map(String).join(' | ');for(const e of ['BLOCKED_MATERIAL_NEAR_DUPLICATE_CONFLICT','EXACT_DUPLICATE','NEAR_DUPLICATE_EQUIVALENT','NEAR_DUPLICATE_MATERIAL_CONFLICT'])assert(sheet.includes(e),`XLSX missing ${e}`);fs.writeFileSync(path.join(dir,'deliverable-truth.json'),JSON.stringify({marker:'P2_DUPLICATE_EVIDENCE_DELIVERABLE_TRUTH=PASS',reportId:report.reportId,formats:{pdf:report.formats.pdf!.sha256,json:report.formats.json!.sha256,xlsx:report.formats.xlsx!.sha256,csv:report.formats.csvLeadSchedules!.sha256}},null,2));console.log('P2_DUPLICATE_EVIDENCE_DELIVERABLE_TRUTH=PASS');
''')

write('server/tests/duplicateEvidenceProductTruthBrowser.test.ts', r'''import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import puppeteer from 'puppeteer-core';import {buildDuplicateEvidenceEngagement,prepareDuplicateEvidence} from './fixtures/duplicateEvidenceAcceptanceHelpers.js';import {DUP_ENGAGEMENT_ID,duplicateEvidenceDir} from './fixtures/duplicateEvidenceFixture.js';const engagement=await buildDuplicateEvidenceEngagement(),p=await prepareDuplicateEvidence(),baseUrl=process.env.EVE_TEST_BASE_URL||'http://127.0.0.1:4173';const candidates=[process.env.CHROME_BIN,'/usr/bin/google-chrome','/usr/bin/google-chrome-stable','/usr/bin/chromium','/usr/bin/chromium-browser'].filter(Boolean) as string[];const executablePath=candidates.find(x=>fs.existsSync(x));if(!executablePath)throw new Error('MISSING_BROWSER_EXECUTABLE');const browser=await puppeteer.launch({executablePath,headless:true,args:['--no-sandbox','--disable-setuid-sandbox','--disable-dev-shm-usage']});try{const page=await browser.newPage();await page.setViewport({width:1440,height:1400});await page.setRequestInterception(true);page.on('request',async req=>{try{const u=new URL(req.url());if(u.origin!==new URL(baseUrl).origin||!u.pathname.startsWith('/api/'))return req.continue();let payload:any={};if(u.pathname==='/api/cpa/engagements/universal')payload={engagements:[{engagementId:engagement.engagementId,workspaceId:engagement.workspaceId,classification:'ACADEMY',isCustomer:false,clientName:engagement.clientName,period:engagement.period,framework:engagement.framework,functionalCurrency:'USD',currentStage:'EVIDENCE_REVIEW',openReviewNotesCount:1,documentsCount:8,canonicalFactsCount:8}]};else if(u.pathname===`/api/cpa/engagements/${DUP_ENGAGEMENT_ID}`)payload={engagement};else if(u.pathname==='/api/cpa/reports/library')payload={reports:[]};else if(u.pathname==='/api/queue/jobs')payload={jobs:[]};else if(u.pathname==='/api/health')payload={status:'ok'};await req.respond({status:200,contentType:'application/json',body:JSON.stringify(payload)});}catch{req.abort();}});const response=await page.goto(`${baseUrl}/?view=engagement-evidence`,{waitUntil:'networkidle0',timeout:30000});assert.ok(response?.ok());const selector='[data-eve-duplicate-evidence="true"]';await page.waitForSelector(selector,{visible:true,timeout:15000});const text=await page.$eval(selector,e=>(e as HTMLElement).innerText);for(const e of ['Duplicate / near-duplicate evidence integrity review','BLOCKED_MATERIAL_NEAR_DUPLICATE_CONFLICT','REQUEST_MATERIAL_SOURCE_RECONCILIATION','Suppressed exact duplicates: 2','Suppressed cosmetic near-duplicates: 2','Material conflicts: 2','Independent corroboration: 2','NOT PROMOTED','EXACT_DUPLICATE','NEAR_DUPLICATE_EQUIVALENT','NEAR_DUPLICATE_MATERIAL_CONFLICT','PDF','IMAGE','USD 53.23','USD 63.23','Corroboration weight: 0'])assert.ok(text.includes(e),`browser missing ${e}`);for(const v of p.conflictReview.variants)assert.ok(text.includes(v.sourceSha256),`browser missing ${v.sourceSha256}`);const screenshot=path.join(duplicateEvidenceDir(),'duplicate-evidence-product-truth.png');await page.screenshot({path:screenshot,fullPage:true});fs.writeFileSync(path.join(duplicateEvidenceDir(),'product-truth.json'),JSON.stringify({marker:'P2_DUPLICATE_EVIDENCE_PRODUCT_TRUTH_BROWSER=PASS',screenshot:path.basename(screenshot),status:p.conflictReview.status,browserVersion:await browser.version()},null,2));console.log('P2_DUPLICATE_EVIDENCE_PRODUCT_TRUTH_BROWSER=PASS');}finally{await browser.close();}
''')

